void veb__Context__preserve_for_response_writer(veb__Context* ctx, veb__Context* user_context) {
	if (!veb__response_body_can_share_gc_buffer()) {
		veb__Context__copy_for_response_writer(ctx, *user_context);
		return;
	}
	bool share_body = (user_context->owned_response_body != NULL) && (user_context->owned_response_body == user_context->res.body.str);
	{
		*ctx = *user_context;
	}
	if (share_body) {
		ctx->shared_response_body = true;
	} else {
		ctx->res.body = string__clone(user_context->res.body);
		ctx->shared_response_body = false;
	}
	ctx->owned_response_body = NULL;
	user_context->owned_response_body = NULL;
	ctx->res.header = veb__clone_response_writer_header(user_context->res.header);
	ctx->res.status_msg = string__clone(user_context->res.status_msg);
	ctx->res.http_version = string__clone(user_context->res.http_version);
	ctx->req.header = veb__clone_response_writer_header(user_context->req.header);
	ctx->return_file = string__clone(user_context->return_file);
}

